<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $plans=get_option('nvconsult_v2_consultation_plans',array()); if(empty($plans)||!is_array($plans)){$plans=array('plan_free'=>array('name'=>__( 'Free Consultation', 'nvconsult-theme-v2' ),'description'=>__( 'A quick strategy session to understand your goals.', 'nvconsult-theme-v2' ),'features'=>"Initial guidance\nEligibility review\nCountry suggestions\nNext-step action plan",'btn_label'=>__( 'Book Free Consultation', 'nvconsult-theme-v2' ),'btn_link'=>'#','icon_class'=>'✓','color'=>'green','visible'=>true),'plan_full'=>array('name'=>__( 'Full Support ★', 'nvconsult-theme-v2' ),'description'=>__( 'Comprehensive support from application to arrival.', 'nvconsult-theme-v2' ),'features'=>"Shortlisting support\nDocument preparation\nVisa assistance\nInterview guidance\nPre-departure prep\nPost-arrival support",'btn_label'=>__( 'Get Full Support', 'nvconsult-theme-v2' ),'btn_link'=>'#','icon_class'=>'★','color'=>'orange','visible'=>true)); } ?>
<section class="section"><div class="section-inner"><?php nvconsultv2_render_section_heading( 'consultation-plans', __( 'Consultation Plans', 'nvconsult-theme-v2' ), __( 'Choose the service level that fits your journey.', 'nvconsult-theme-v2' ) ); ?><div class="plans-grid"><?php foreach($plans as $plan): if(empty($plan['visible'])){continue;} ?><article class="plan-card plan-card--<?php echo esc_attr( $plan['color'] ); ?>"><p class="badge"><?php echo esc_html( $plan['icon_class'] ); ?></p><h3><?php echo esc_html( $plan['name'] ); ?></h3><p><?php echo esc_html( $plan['description'] ); ?></p><ul class="plan-features"><?php foreach(preg_split('/\r\n|\r|\n/',$plan['features']) as $feature): if(''!==trim($feature)): ?><li><?php echo esc_html( trim( $feature ) ); ?></li><?php endif; endforeach; ?></ul><a class="<?php echo esc_attr( nvconsultv2_button_class( $plan['color'] ) ); ?>" href="<?php echo esc_url( $plan['btn_link'] ); ?>"><?php echo esc_html( $plan['btn_label'] ); ?></a></article><?php endforeach; ?></div></div></section>
